R=[[0,36,3,41,18],[1,44,10,45,2],[62,6,43,15,61],[28,55,25,21,56],[27,20,39,8,14]]
M=(1<<64)-1
def rol(x,n):
    n%=64; return ((x<<n)|(x>>(64-n)))&M
def f(A):
    for rnd in range(24):
        C=[A[x][0]^A[x][1]^A[x][2]^A[x][3]^A[x][4] for x in range(5)]
        D=[C[(x-1)%5]^rol(C[(x+1)%5],1) for x in range(5)]
        for x in range(5):
            for y in range(5): A[x][y]^=D[x]
        B=[[0]*5 for _ in range(5)]
        for x in range(5):
            for y in range(5): B[y][(2*x+3*y)%5]=rol(A[x][y],R[x][y])
        for x in range(5):
            for y in range(5): A[x][y]=B[x][y]^((~B[(x+1)%5][y])&B[(x+2)%5][y]&M)
        A[0][0]^=RC[rnd]
    return A
def keccak256(data:bytes)->str:
    rate=136; data=bytearray(data); data.append(0x01)
    while len(data)%rate: data.append(0)
    data[-1]^=0x80
    A=[[0]*5 for _ in range(5)]
    for off in range(0,len(data),rate):
        blk=data[off:off+rate]
        for i in range(rate//8):
            A[i%5][i//5]^=int.from_bytes(blk[i*8:(i+1)*8],'little')
        A=f(A)
    out=b''
    for i in range(4): out+=A[i%5][i//5].to_bytes(8,'little')
    return out.hex()
